<?php if($draftWorkspace&&!$draft): ?>
<?php include __DIR__.'/inbox-selection-empty.php'; ?>
<?php else: ?>
<?php if($draftWorkspace): ?>
<header class="inbox-conversation-heading inbox-draft-heading"><div class="inbox-conversation-context"><?php $icon('draft'); ?><span>Private draft · Only visible to you</span></div><h1 data-inbox-draft-subject><?= $h($draft['subject']?:'(No subject)') ?></h1><p>Last edited <?php $time($draft['updated_at']); ?></p></header>
<?php endif; ?>
<div class="<?= $draftWorkspace?'inbox-draft-content':'inbox-compose-panel' ?>">
<?php if(!$draftWorkspace): ?><h1><?= $threadId?'Reply':'Compose a message' ?></h1><?php endif; ?>
<?php if(!$draft&&!$recipient&&!$thread): ?><h2>Who would you like to send a message to?</h2><form method="get" class="inbox-recipient-search"><input type="hidden" name="view" value="inbox"><input type="hidden" name="panel" value="compose"><label>To:<input name="recipient_query" data-inbox-recipient-search maxlength="100" value="<?= $h($_GET['recipient_query']??'') ?>" autocomplete="off" placeholder="Search subscribed connections"></label><button>Search</button></form><ul class="inbox-recipients" data-inbox-recipients><?php foreach(isset($_GET['recipient_query'])?$store->inboxRecipients(audienceText($_GET,'recipient_query',100)):[]as$p): ?><li><a href="<?= $h($url(['panel'=>'compose','contact'=>(int)$p['id']])) ?>"><?= $h(trim($p['first_name'].' '.$p['last_name']).' <'.$p['email'].'>') ?></a></li><?php endforeach; ?></ul>
<?php else: ?>
<?php if($draft&&$draft['state']!=='draft'): ?><p>This draft has already been <?= $h($draft['state']) ?>.</p><?php else: ?><p>To: <strong><?= $h($recipient['email']??$thread['sender_email']??'') ?></strong></p>
<form method="post" class="inbox-compose-form" data-inbox-compose><?php $form('inbox_draft_save',['draft_id'=>$draftId,'version'=>$draft['version']??0,'thread_id'=>$threadId,'contact_id'=>$recipient['id']??0]); ?><label>From name<input name="from_name" maxlength="100" value="<?= $h($draft['from_name']??$displayName) ?>"></label><label>Subject<input name="subject" maxlength="250" required value="<?= $h($draft['subject']??($thread?'Re: '.$thread['subject']:'')) ?>"></label>
<label>Message template<select data-inbox-template><option value="">Choose a template</option><?php foreach($templates as$t): ?><option value="<?= (int)$t['id'] ?>"><?= $h($t['name']) ?></option><?php endforeach; ?></select></label><?php $rich($draft['body_html']??''); ?><p class="inbox-muted">Personalization: *|FNAME|*, *|LNAME|*, *|EMAIL|*, *|LIST:COMPANY|*</p><label class="inbox-check"><input type="checkbox" name="include_optout" value="1"<?= !$draft||$draft['include_optout']?' checked':'' ?>>Include an opt-out link for one-to-one messages</label><div class="inbox-actions"><button class="primary" name="save">Save draft</button><button type="button" data-inbox-send<?= !$canSend||!$readiness['ready']||$replyReasons?' disabled':'' ?>>Send message</button><span data-inbox-save-status role="status"></span></div></form>
<?php if(!$readiness['ready']||$replyReasons||!$canSend): ?><div class="inbox-gate"><strong>Before you can send</strong><ul><?php foreach(array_merge($readiness['reasons'],$replyReasons,!$canSend?['Sending is unavailable in this access mode.']:[])as$reason): ?><li><?= $h($reason) ?></li><?php endforeach; ?></ul></div><?php endif; ?>
<?php if($draftId): ?><section class="inbox-attachments"><h2>Attachments</h2><p>PDF, JPG, PNG, or GIF. Up to 5 MB each, 6 MB total, and 10 files.</p><?php foreach($draft['attachments']as$a): ?><form method="post"><?php $form('inbox_attachment',['draft_id'=>$draftId,'version'=>$draft['version'],'remove'=>$a['id']]); ?><a href="<?= $h($url(['attachment'=>(int)$a['id']])) ?>"><?= $h($a['filename']) ?></a><button>Remove</button></form><?php endforeach; ?><form method="post" enctype="multipart/form-data"><?php $form('inbox_attachment',['draft_id'=>$draftId,'version'=>$draft['version']]); ?><label>Choose attachment<input type="file" name="attachment" accept=".pdf,.jpg,.jpeg,.png,.gif" data-file-help="PDF, JPEG, PNG or GIF · up to 5 MB" data-file-max-bytes="5000000" required></label><button>Attach file</button></form></section><form method="post" data-confirm="Discard this private draft?"><?php $form('inbox_draft_discard',['draft_id'=>$draftId,'version'=>$draft['version']]); ?><button>Discard draft</button></form><?php else: ?><p>Save your draft before attaching files.</p><?php endif; ?><?php endif; ?><?php endif; ?>
</div>
<?php endif; ?>
